}

Method.Source:
/// <summary>
/// Extension of the method <m>modified</m>
/// </summary>
/// <returns>boolean</returns>
public boolean modified()
{
    boolean ret;

    ret = next modified();
    FormCheckBoxControl fc = this;
    FormComboBoxControl editProcessOptions = fc.formRun().design().controlName(formControlStr(AVAFPLLedgerAllocationRequest, editProcessOptions));
    FormCheckBoxControl postCostAllocationJournal = fc.formRun().design().controlName(formControlStr(AVAFPLLedgerAllocationRequest, AVAPostCostAllocationJournal));
    FormCheckBoxControl summarizeValues =  fc.formRun().design().controlName(formControlStr(AVAFPLLedgerAllocationRequest, AVASummarizeValues));
    if (fc.checked())
    {
        editProcessOptions.selection(LedgerAllocationProcessMode::ProposalOnly);
        editProcessOptions.enabled(false);
        postCostAllocationJournal.enabled(true);
        summarizeValues.enabled(true);
    }
    else
    {
        editProcessOptions.enabled(true);
        postCostAllocationJournal.enabled(false);
        postCostAllocationJournal.checked(false);
        summarizeValues.enabled(false);
        summarizeValues.checked(false);
    }

    return ret;
}
